1	import { ok, fail } from './result.js';
2	import { formatEuros } from './money.js';
3	import { getCustomer } from './customers.js';
4	import { invoiceTotals, lineTotal, lineVAT, lineDiscount, bulkDiscount } from './invoices.js';
5	import { balanceDue } from './payments.js';
6	
7	/**
8	 * Render an invoice as plain text.
9	 * @param {{ customerId: string, number?: string, lines: Array, voucher?: { code: string, amount: number }, dueDate?: string, payments?: Array }} invoice
10	 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
11	 */
12	export function renderInvoiceText(invoice) {
13	  // Get customer name
14	  const customerResult = getCustomer(invoice.customerId);
15	  if (!customerResult.ok) {
16	    return customerResult;
17	  }
18	
19	  const customer = customerResult.value;
20	  const number = invoice.number || 'DRAFT';
21	
22	  // Build lines
23	  const lines = [
24	    number,
25	    customer.name,
26	  ];
27	
28	  // Add invoice lines with discounts
29	  for (const line of invoice.lines) {
30	    const total = lineTotal(line);
31	    let lineText = `${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
32	
33	    // Add line discount if present
34	    const lineDisc = lineDiscount(line);
35	    const bulkDisc = bulkDiscount(line);
36	    const totalDisc = lineDisc + bulkDisc;
37	
38	    if (totalDisc > 0) {
39	      lineText += ` (${formatEuros(totalDisc)} discount)`;
40	    }
41	
42	    lines.push(lineText);
43	  }
44	
45	  // Get totals
46	  const { vat, total, discount, voucher } = invoiceTotals(invoice);
47	
48	  // Add discount line if there are any discounts
49	  if (discount > 0) {
50	    lines.push(`Discount: ${formatEuros(discount)}`);
51	  }
52	
53	  // Add VAT if present
54	  if (vat > 0) {
55	    lines.push(`VAT: ${formatEuros(vat)}`);
56	  }
57	
58	  // Add voucher if present
59	  if (voucher > 0) {
60	    lines.push(`Voucher: -${formatEuros(voucher)}`);
61	  }
62	
63	  // Add total
64	  lines.push(`Total: ${formatEuros(total)}`);
65	
66	  // Add due date if present
67	  if (invoice.dueDate) {
68	    lines.push(`Due: ${invoice.dueDate}`);
69	  }
70	
71	  // Add amount paid if there are payments
72	  if (invoice.payments && invoice.payments.length > 0) {
73	    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
74	    lines.push(`Paid: ${formatEuros(totalPaid)}`);
75	  }
76	
77	  return ok(lines.join('\n'));
78	}
