11	/**
12	 * Create an invoice.
13	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
14	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
15	 */
16	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
17	  // Normalize customer ID
18	  const normalizedCustomerId = normalizeId(customerId);
19	
20	  // Validate customer exists
21	  const customerResult = getCustomer(normalizedCustomerId);
22	  if (!customerResult.ok) {
23	    return customerResult;
24	  }
25	
26	  const customer = customerResult.value;
27	
28	  // Validate issue date format and validity
29	  if (!isValidDate(issueDate)) {
30	    return fail('DATE_INVALID');
31	  }
32	
33	  // Validate terms
34	  const validTerms = ['NET14', 'NET30', 'EOM'];
35	  if (!validTerms.includes(terms)) {
36	    return fail('TERMS_INVALID');
37	  }
38	
39	  // Calculate due date
40	  const dueDate = calculateDueDate(issueDate, terms);
41	
42	  // Validate lines is not empty
43	  if (!lines || lines.length === 0) {
44	    return fail('NO_LINES');
45	  }
46	
47	  // Build and validate invoice lines
48	  const invoiceLines = [];
49	  for (const line of lines) {
50	    // Validate qty
51	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
52	      return fail('QTY_INVALID');
53	    }
54	
55	    // Determine discount: explicit discountPercent wins, otherwise use tier discount
56	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
57	
58	    // Validate discountPercent
59	    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
60	      return fail('DISCOUNT_INVALID');
61	    }
62	
63	    // Look up product
64	    const productResult = getProduct(line.sku);
65	    if (!productResult.ok) {
66	      return productResult;
67	    }
68	
69	    const product = productResult.value;
70	    invoiceLines.push({
71	      sku: line.sku,
72	      name: product.name,
73	      qty: line.qty,
74	      unitPrice: product.unitPrice,
75	      vatRate: product.vatRate,
76	      discountPercent,
77	    });
78	  }
79	
80	  return ok({
81	    customerId: normalizedCustomerId,
82	    issueDate,
83	    status: 'draft',
84	    lines: invoiceLines,
85	    terms,
86	    dueDate,
87	  });
88	}
89	
