91	/**
92	 * Add or update a line on an invoice.
93	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
94	 * @param {{ sku: string, qty: number, discountPercent?: number }}
95	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
96	 */
97	export function addLine(invoice, { sku, qty, discountPercent }) {
98	  // Check status is draft
99	  if (invoice.status !== 'draft') {
100	    return fail('NOT_DRAFT');
101	  }
102	
103	  // Validate qty
104	  if (!Number.isInteger(qty) || qty <= 0) {
105	    return fail('QTY_INVALID');
106	  }
107	
108	  // Validate discountPercent
109	  const discount = discountPercent ?? 0;
110	  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
111	    return fail('DISCOUNT_INVALID');
112	  }
113	
114	  // Look up product
115	  const productResult = getProduct(sku);
116	  if (!productResult.ok) {
117	    return productResult;
118	  }
119	
120	  const product = productResult.value;
121	
122	  // Create new lines array
123	  const newLines = invoice.lines.map((line) => ({ ...line }));
124	
125	  // Check if SKU already exists
126	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
127	
128	  if (existingLineIndex !== -1) {
129	    // Update existing line's qty
130	    newLines[existingLineIndex] = {
131	      ...newLines[existingLineIndex],
132	      qty: newLines[existingLineIndex].qty + qty,
133	    };
134	  } else {
135	    // Add new line
136	    newLines.push({
137	      sku,
138	      name: product.name,
139	      qty,
140	      unitPrice: product.unitPrice,
141	      vatRate: product.vatRate,
142	      discountPercent: discount,
143	    });
144	  }
145	
146	  return ok({
147	    customerId: invoice.customerId,
148	    issueDate: invoice.issueDate,
149	    status: invoice.status,
150	    lines: newLines,
151	  });
152	}
153	
154	/**
155	 * Remove a line from an invoice.
156	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }}
157	 * @param {string} sku
158	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
159	 */
160	export function removeLine(invoice, sku) {
161	  // Check status is draft
162	  if (invoice.status !== 'draft') {
163	    return fail('NOT_DRAFT');
164	  }
165	
166	  // Find the line to remove
167	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
168	
169	  if (lineIndex === -1) {
170	    return fail('LINE_NOT_FOUND');
171	  }
172	
173	  // Check if this is the last line
174	  if (invoice.lines.length === 1) {
175	    return fail('NO_LINES');
176	  }
177	
178	  // Create new lines array without the removed line
179	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
180	
181	  return ok({
182	    customerId: invoice.customerId,
183	    issueDate: invoice.issueDate,
184	    status: invoice.status,
185	    lines: newLines,
186	  });
187	}
188	
189	/**
190	 * Apply a voucher to a draft invoice.
191	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: { code: string, amount: number } }} invoice
192	 * @param {{ code: string, amount: number }}
193	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, voucher: { code: string, amount: number } } } | { ok: false, error: string }}
194	 */
195	export function applyVoucher(invoice, { code, amount }) {
196	  // Check status is draft
197	  if (invoice.status !== 'draft') {
198	    return fail('NOT_DRAFT');
199	  }
200	
201	  // Check if voucher already exists
202	  if (invoice.voucher) {
203	    return fail('VOUCHER_EXISTS');
204	  }
205	
206	  // Validate amount is a positive integer
207	  if (!Number.isInteger(amount) || amount <= 0) {
208	    return fail('AMOUNT_INVALID');
209	  }
210	
211	  return ok({
212	    customerId: invoice.customerId,
213	    issueDate: invoice.issueDate,
214	    status: invoice.status,
215	    lines: invoice.lines.map((line) => ({ ...line })),
216	    ...(invoice.terms && { terms: invoice.terms }),
217	    ...(invoice.dueDate && { dueDate: invoice.dueDate }),
218	    voucher: { code, amount },
219	  });
220	}
221	
222	/**
223	 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
224	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } }} invoice
225	 * @param {Array<string>} existingNumbers - Invoice numbers already issued
226	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, number: string, lines: Array, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } } } | { ok: false, error: string }}
227	 */
228	export function issueInvoice(invoice, existingNumbers) {
229	  // Check status is draft
230	  if (invoice.status !== 'draft') {
231	    return fail('NOT_DRAFT');
232	  }
233	
234	  // Generate next invoice number
235	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
236	
237	  return ok({
238	    customerId: invoice.customerId,
239	    issueDate: invoice.issueDate,
240	    status: 'issued',
241	    number,
242	    lines: invoice.lines.map((line) => ({ ...line })),
243	    ...(invoice.terms && { terms: invoice.terms }),
244	    ...(invoice.dueDate && { dueDate: invoice.dueDate }),
245	    ...(invoice.voucher && { voucher: { ...invoice.voucher } }),
246	  });
247	}
